// 50 visually distinct mobile app layout renderers.
// Each function takes ctx (brand config) and returns HTML for a unique layout.
import { ctxd, phoneNav, tabbar, feedItem, ln, lines, kpi, card, bar, pill, chip, btn, avatar, FS } from "./layoutHelpers.js";

const M = {};

// 1. feed-list
M["feed-list"] = (ctx) => phoneNav(ctx) + `<div class="vg-scroll" style="flex:1;overflow:auto"><div class="vg-feed">${feedItem(ctx.brandName+" live","Sarah · 2h",90)}${feedItem("New lead from website","Auto · 5h",60)}${feedItem("Quarterly report ready","Daniel · 1d",75)}</div></div><div class="vg-fab">+</div>` + tabbar(["Home","Search","Inbox","Me"],0);

// 2. card-swipe
M["card-swipe"] = (ctx) => `<div class="vg-media"><div class="progress"><i></i></div><div style="flex:1"></div><div class="overlay"><div class="vg-col" style="gap:4px"><div style="font-weight:900;${FS(13)}">@${(ctx.logoText||"").toLowerCase().replace(/\s+/g,"")}</div><div style="${FS(9)};opacity:.85;max-width:180px">${ctx.subtitle}</div></div><div class="actions"><div class="a">♥</div><div class="a">💬</div><div class="a">↗</div></div></div></div>` + tabbar(["For You","Following","Live"],0);

// 3. tile-grid
M["tile-grid"] = (ctx) => phoneNav(ctx) + `<div class="vg-scroll" style="flex:1;overflow:auto"><div style="padding:12px 12px 10px"><div style="font-weight:900;${FS(15)}">${ctx.heading}</div><div class="vg-muted" style="${FS(9)}">${ctx.subtitle}</div></div><div class="vg-tiles"><div class="tile"><div class="ic">$</div><div class="v">$48.2k</div><div class="l">Revenue</div></div><div class="tile"><div class="ic">↑</div><div class="v">62</div><div class="l">Leads</div></div><div class="tile"><div class="ic">◷</div><div class="v">12</div><div class="l">Tasks</div></div><div class="tile"><div class="ic">★</div><div class="v">4.9</div><div class="l">Rating</div></div></div><div style="padding:0 12px 10px"><div class="vg-card"><div style="${FS(10)};font-weight:700;margin-bottom:6px">Recent</div><div class="vg-feed">${feedItem(ctx.brandName+" booked","Today",70)}</div></div></div></div>` + tabbar(["Home","Activity","Inbox","Me"],0);

// 4. search-explore
M["search-explore"] = (ctx) => `<div class="vg-search"><div class="f"><span style="${FS(11)}">🔍</span><span style="${FS(10)};color:var(--brand-muted-foreground)">Search places…</span><div style="flex:1"></div>${chip("Nearby")}</div><div class="vg-row vg-gap2" style="margin-top:8px">${chip("Cafés")}${chip("Shops",false)}${chip("Services",false)}</div></div><div class="vg-scroll" style="flex:1;overflow:auto"><div class="vg-feed"><div class="item"><div class="thumb"></div><div class="body"><div class="ttl">${ctx.brandName}</div><div class="meta">★ 4.8 · 0.4 mi · Café</div><div class="ln" style="width:70%"></div></div></div><div class="item"><div class="thumb"></div><div class="body"><div class="ttl">Atlas Studio</div><div class="meta">★ 4.9 · 0.8 mi · Design</div><div class="ln" style="width:55%"></div></div></div><div class="item"><div class="thumb"></div><div class="body"><div class="ttl">Northwind Bakery</div><div class="meta">★ 4.7 · 1.2 mi · Bakery</div><div class="ln" style="width:65%"></div></div></div></div></div>` + tabbar(["Explore","Saved","Profile"],0);

// 5. generic-list
M["generic-list"] = (ctx) => phoneNav(ctx) + `<div class="vg-scroll" style="flex:1;overflow:auto"><div style="padding:12px"><div style="font-weight:900;${FS(14)}">Inbox</div><div class="vg-muted" style="${FS(9)};margin-bottom:8px">3 new messages</div></div><div class="vg-feed">${feedItem("Sarah K. — "+ctx.brandName,"2h ago",85)}${feedItem("Daniel R. — Quote ready","5h ago",60)}${feedItem("System — Weekly digest","1d ago",70)}</div></div>` + tabbar(["Home","Inbox","Me"],0);

// 6. onboarding-carousel
M["onboarding-carousel"] = (ctx) => `<div style="flex:1;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;padding:24px;background:linear-gradient(160deg,var(--brand-muted),var(--brand-surface))"><div style="width:64px;height:64px;border-radius:14px;background:rgba(0,89,255,.12);color:var(--brand-gold-deep);display:flex;align-items:center;justify-content:center;margin-bottom:16px"><span style="${FS(30)}">✦</span></div><div style="${FS(18)};font-weight:900">${ctx.heading}</div><div class="vg-muted" style="${FS(11)};margin-top:6px;max-width:220px">${ctx.subtitle}</div><div class="vg-row vg-gap2" style="margin-top:18px">${[0,1,2].map(i=>`<div style="width:7px;height:7px;border-radius:9999px;background:${i===0?"var(--brand-primary)":"var(--brand-muted)"}"></div>`).join("")}</div></div><div class="vg-row vg-between" style="padding:14px 18px;border-top:1px solid var(--brand-border)">${btn("Skip",false)}${btn("Next")}</div>`;

// 7. qr-scanner
M["qr-scanner"] = (ctx) => `<div style="flex:1;display:flex;flex-direction:column;justify-content:center;align-items:center;background:#0b1020;color:#fff;padding:20px"><div style="width:200px;height:200px;border:2px solid #ffffff44;border-radius:16px;position:relative"><div style="position:absolute;left:14px;right:14px;top:50%;height:2px;background:linear-gradient(90deg,transparent,var(--brand-gold-bright),transparent);box-shadow:0 0 12px var(--brand-gold-bright)"></div><div style="position:absolute;top:14px;left:14px;width:24px;height:24px;border-top:3px solid var(--brand-primary);border-left:3px solid var(--brand-primary);border-radius:6px 0 0 0"></div><div style="position:absolute;top:14px;right:14px;width:24px;height:24px;border-top:3px solid var(--brand-primary);border-right:3px solid var(--brand-primary);border-radius:0 6px 0 0"></div><div style="position:absolute;bottom:14px;left:14px;width:24px;height:24px;border-bottom:3px solid var(--brand-primary);border-left:3px solid var(--brand-primary);border-radius:0 0 0 6px"></div><div style="position:absolute;bottom:14px;right:14px;width:24px;height:24px;border-bottom:3px solid var(--brand-primary);border-right:3px solid var(--brand-primary);border-radius:0 0 6px 0"></div></div><div style="${FS(11)};margin-top:18px;opacity:.85">Align QR within frame</div></div>` + tabbar(["Scan","History","Profile"],0);

// 8. checkout-flow
M["checkout-flow"] = (ctx) => {const items=[["Pro plan","$49.00"],["Add-on seats (3)","$18.00"],["Tax","$5.34"]];return phoneNav(ctx)+`<div class="vg-scroll" style="flex:1;overflow:auto;padding:12px"><div style="${FS(15)};font-weight:900">Checkout</div><div class="vg-muted" style="${FS(9)};margin-top:2px">Order summary</div><div class="vg-card" style="margin-top:10px">${items.map(it=>`<div class="vg-row vg-between" style="margin-bottom:6px"><span style="${FS(10)}">${it[0]}</span><span style="${FS(10)};font-weight:700">${it[1]}</span></div>`).join("")}<div style="border-top:1px solid var(--brand-border);margin-top:6px;padding-top:6px" class="vg-row vg-between"><span style="${FS(10)};font-weight:700">Total</span><span style="${FS(12)};font-weight:900;color:var(--brand-primary)">$72.34</span></div></div><div style="${FS(10)};font-weight:700;margin-top:12px;margin-bottom:6px">Payment</div><div style="display:flex;align-items:center;gap:8px;padding:10px;border:1px solid var(--brand-border);border-radius:10px;background:var(--brand-muted)"><div style="width:28px;height:18px;border-radius:4px;background:linear-gradient(135deg,var(--brand-gold-light),var(--brand-primary))"></div><span style="${FS(10)};font-weight:700">•••• 4242</span></div></div><div style="padding:12px;border-top:1px solid var(--brand-border)"><button class="vg-btn pri" style="width:100%;padding:11px">Pay $72.34</button></div>`;};

// 9. fitness-rings
M["fitness-rings"] = (ctx) => {const ring=(p,color)=>`conic-gradient(${color} ${p*360}deg, transparent 0)`;return phoneNav(ctx)+`<div class="vg-scroll" style="flex:1;overflow:auto;padding:12px"><div style="${FS(15)};font-weight:900">Today</div><div class="vg-muted" style="${FS(9)}">Activity</div><div style="display:flex;justify-content:center;margin:14px 0"><div style="position:relative;width:130px;height:130px"><div style="position:absolute;inset:0;border-radius:9999px;background:${ring(0.82,"var(--brand-primary)")}"></div><div style="position:absolute;inset:14px;border-radius:9999px;background:${ring(0.6,"var(--brand-gold-bright)")}"></div><div style="position:absolute;inset:28px;border-radius:9999px;background:${ring(0.45,"var(--brand-gold-deep)")}"></div><div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center"><div style="${FS(18)};font-weight:900">82%</div><div class="vg-muted" style="${FS(8)}">of goals</div></div></div></div><div class="vg-tiles"><div class="tile"><div class="ic">↑</div><div class="v">8,420</div><div class="l">Steps</div></div><div class="tile"><div class="ic">♥</div><div class="v">142</div><div class="l">BPM</div></div><div class="tile"><div class="ic">◷</div><div class="v">48m</div><div class="l">Active</div></div><div class="tile"><div class="ic">★</div><div class="v">4.9</div><div class="l">Streak</div></div></div></div>`+tabbar(["Today","History","Me"],0);};

// 10. food-menu
M["food-menu"] = (ctx) => {const cats=["Pizza","Burgers","Sides","Drinks"];const items=[["Margherita","$12"],["Pepperoni","$14"],["Veggie Supreme","$15"],["BBQ Chicken","$16"]];return phoneNav(ctx)+`<div style="display:flex;gap:6px;padding:8px 12px;overflow:auto;border-bottom:1px solid var(--brand-border);flex:none">${cats.map((c,i)=>chip(c,i===0)).join("")}</div><div class="vg-scroll" style="flex:1;overflow:auto;padding:10px">${items.map(it=>`<div class="vg-card" style="display:flex;align-items:center;gap:9px;margin-bottom:8px"><div style="width:42px;height:42px;border-radius:9px;background:linear-gradient(135deg,var(--brand-gold-light),var(--brand-primary),var(--brand-gold-deep));flex:none"></div><div style="flex:1"><div style="${FS(11)};font-weight:700">${it[0]}</div><div class="vg-muted" style="${FS(9)}">Cheesy · 12"</div></div><div style="${FS(11)};font-weight:900;color:var(--brand-primary)">${it[1]}</div>${btn("+")}</div>`).join("")}</div><div class="vg-row vg-between" style="padding:12px;border-top:1px solid var(--brand-border)"><div><span style="${FS(10)};font-weight:700">2 items</span><div style="${FS(13)};font-weight:900">$26.00</div></div>${btn("View cart")}</div>`;};

// 11. ride-tracking
M["ride-tracking"] = (ctx) => `<div style="flex:1;position:relative;background:linear-gradient(135deg,#e6f0ff,#cfe0ff);overflow:hidden"><div style="position:absolute;inset:0;background-image:linear-gradient(var(--brand-border) 1px,transparent 1px),linear-gradient(90deg,var(--brand-border) 1px,transparent 1px);background-size:28px 28px;opacity:.6"></div><div style="position:absolute;left:30%;top:30%;width:12px;height:12px;border-radius:9999px;background:var(--brand-primary);box-shadow:0 0 0 6px rgba(0,89,255,.2)"></div><div style="position:absolute;right:25%;bottom:35%;width:12px;height:12px;border-radius:9999px;background:var(--brand-gold-deep)"></div><svg style="position:absolute;inset:0;width:100%;height:100%" viewBox="0 0 100 100" preserveAspectRatio="none"><path d="M30,30 Q50,20 75,65" stroke="var(--brand-primary)" stroke-width="1.5" fill="none" stroke-dasharray="3,2"/></svg></div><div style="padding:14px;border-top:1px solid var(--brand-border);background:var(--brand-surface)"><div style="width:40px;height:4px;background:var(--brand-border);border-radius:9999px;margin:0 auto 10px"></div><div class="vg-row vg-between"><div><div style="${FS(13)};font-weight:900">3 min away</div><div class="vg-muted" style="${FS(9)}">Sarah · Toyota Camry · 4XK 921</div></div><div style="${FS(16)};font-weight:900;color:var(--brand-primary)">$8.40</div></div><button class="vg-btn pri" style="width:100%;margin-top:10px;padding:11px">Cancel ride</button></div>`;

// 12. notes-list
M["notes-list"] = (ctx) => {const notes=[["Q4 strategy","Bullet points and OKRs…","2h"],["Meeting notes","Action items from sync…","Yest."],["Ideas","New onboarding flow…","Mon"],["Reading list","Books and articles…","Last wk"]];return phoneNav(ctx)+`<div class="vg-scroll" style="flex:1;overflow:auto;padding:10px"><div style="display:flex;align-items:center;gap:6px;padding:7px 11px;border:1px solid var(--brand-border);border-radius:9999px;background:var(--brand-muted);margin-bottom:10px"><span style="${FS(11)}">🔍</span><span class="vg-muted" style="${FS(10)}">Search notes…</span></div>${notes.map(n=>`<div class="vg-card" style="margin-bottom:8px"><div style="${FS(11)};font-weight:700">${n[0]}</div><div class="vg-muted" style="${FS(9)};margin-top:3px">${n[1]}</div><div class="vg-muted" style="${FS(8)};margin-top:6px">${n[2]}</div></div>`).join("")}</div><div class="vg-fab">+</div>`+tabbar(["Notes","Shared","Me"],0);};

// 13. habit-tracker
M["habit-tracker"] = (ctx) => {const habits=[["Morning run","12 day streak"],["Read 20 min","5 day streak"],["No sugar","3 day streak"],["Meditate","21 day streak"]];const cells=Array.from({length:28},(_,i)=>i%7<3?1:0);return phoneNav(ctx)+`<div class="vg-scroll" style="flex:1;overflow:auto;padding:12px"><div style="${FS(15)};font-weight:900">Habits</div><div class="vg-muted" style="${FS(9)}">4 active · 12 day best streak</div><div style="display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin:12px 0">${cells.map(c=>`<div style="aspect-ratio:1;border-radius:5px;background:${c?"var(--brand-primary)":"var(--brand-muted)"};opacity:${c?0.9:0.5}"></div>`).join("")}</div>${habits.map(h=>`<div class="vg-card" style="display:flex;align-items:center;gap:9px;margin-bottom:7px"><div style="width:32px;height:32px;border-radius:8px;background:rgba(0,89,255,.12);color:var(--brand-gold-deep);display:flex;align-items:center;justify-content:center"><span style="${FS(13)}">🔥</span></div><div style="flex:1"><div style="${FS(11)};font-weight:700">${h[0]}</div><div class="vg-muted" style="${FS(9)}">${h[1]}</div></div><div style="width:22px;height:22px;border-radius:9999px;background:var(--brand-primary);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:900;${FS(11)}">✓</div></div>`).join("")}</div>`+tabbar(["Today","Habits","Stats"],0);};

// 14. event-ticket
M["event-ticket"] = (ctx) => phoneNav(ctx)+`<div class="vg-scroll" style="flex:1;overflow:auto;padding:12px;display:flex;flex-direction:column;align-items:center"><div style="width:100%;max-width:260px;border-radius:14px;overflow:hidden;background:linear-gradient(160deg,var(--brand-secondary),var(--brand-primary))"><div style="padding:14px;color:#fff"><div style="${FS(9)};opacity:.8;text-transform:uppercase;letter-spacing:.05em">Admit one</div><div style="${FS(16)};font-weight:900;margin-top:4px">Atlas Summit 2026</div><div style="${FS(10)};opacity:.85;margin-top:4px">Fri, Oct 16 · 7:00 PM</div><div style="${FS(10)};opacity:.85">Grand Hall · NYC</div></div><div style="height:1px;border-top:2px dashed #ffffff55;margin:0 10px"></div><div style="padding:14px;display:flex;flex-direction:column;align-items:center;background:#ffffff11"><div style="width:90px;height:90px;background:#fff;border-radius:8px;display:grid;grid-template-columns:repeat(8,1fr);gap:1px;padding:6px">${Array.from({length:64},(_,i)=>`<div style="background:${(i*7)%3===0?"#000":"transparent"}"></div>`).join("")}</div><div style="${FS(8)};color:#fff;margin-top:6px;opacity:.85">TX-441-2026</div></div></div><button class="vg-btn pri" style="width:100%;max-width:260px;margin-top:12px">Add to wallet</button></div>`+tabbar(["Tickets","Events","Me"],0);

// 15. forum-threads
M["forum-threads"] = (ctx) => {const threads=[["Best onboarding flow?","42 replies · 1.2k views","discuss"],["Show & tell: new dashboard","18 replies · 830 views","showcase"],["How do you handle churn?","27 replies · 640 views","discuss"],["Hiring: design lead","9 replies · 210 views","jobs"]];return phoneNav(ctx)+`<div class="vg-scroll" style="flex:1;overflow:auto;padding:10px">${threads.map((th,i)=>`<div class="vg-card" style="margin-bottom:8px"><div class="vg-row vg-gap2" style="margin-bottom:5px">${chip(th[2],false)}<div style="flex:1"></div><span class="vg-muted" style="${FS(8)}">${i+1}d</span></div><div style="${FS(11)};font-weight:700">${th[0]}</div><div class="vg-muted" style="${FS(9)};margin-top:4px">${th[1]}</div><div class="vg-row vg-gap2" style="margin-top:8px"><span style="${FS(9)};font-weight:700;color:var(--brand-primary)">▲ 24</span><span class="vg-muted" style="${FS(9)}">💬 12</span><span class="vg-muted" style="${FS(9)}">↗</span></div></div>`).join("")}</div><div class="vg-fab">+</div>`+tabbar(["Feed","Tags","Me"],0);};

// 16. course-player
M["course-player"] = (ctx) => {const lessons=[["Intro to the platform","8:24","done"],["Setting up your workspace","12:10","done"],["Building your first app","18:42","current"],["Publishing & sharing","9:15","todo"],["Analytics basics","14:30","todo"]];const ic=s=>s==="done"?"✓":s==="current"?"▶":"○";return phoneNav(ctx)+`<div style="background:linear-gradient(135deg,var(--brand-secondary),var(--brand-primary));padding:14px;color:#fff;flex:none"><div style="${FS(9)};opacity:.8;text-transform:uppercase;letter-spacing:.05em">Course · 5 lessons</div><div style="${FS(14)};font-weight:900;margin-top:3px">Platform Fundamentals</div><div class="vg-bar" style="margin-top:8px;background:#ffffff33"><i style="width:40%"></i></div><div style="${FS(9)};opacity:.85;margin-top:5px">2 of 5 complete</div></div><div class="vg-scroll" style="flex:1;overflow:auto;padding:10px">${lessons.map(l=>`<div class="vg-row vg-gap2" style="align-items:center;padding:9px;border-radius:9px;margin-bottom:5px;${l[2]==="current"?"background:var(--brand-muted)":""}"><div style="width:24px;height:24px;border-radius:9999px;display:flex;align-items:center;justify-content:center;${FS(10)};font-weight:800;${l[2]==="done"||l[2]==="current"?"background:var(--brand-primary);color:#fff":"border:1px solid var(--brand-border);color:var(--brand-muted-foreground)"}">${ic(l[2])}</div><div style="flex:1"><div style="${FS(10)};font-weight:700">${l[0]}</div><div class="vg-muted" style="${FS(8)}">${l[1]}</div></div></div>`).join("")}</div>`+tabbar(["Learn","Library","Me"],0);};

// 17. health-vitals
M["health-vitals"] = (ctx) => {const bars=[62,70,68,75,72,80,76,84,78,88,82,90].map(h=>`<i style="height:${h}%"></i>`).join("");const readings=[["♥","72","Heart rate"],["⊕","118","Blood pressure"],["◐","94","Blood glucose"],["◷","7h","Sleep"]];return phoneNav(ctx)+`<div class="vg-scroll" style="flex:1;overflow:auto;padding:12px"><div style="${FS(15)};font-weight:900">Health</div><div class="vg-muted" style="${FS(9)}">Today · updated 2m ago</div><div class="vg-card" style="margin-top:10px"><div style="${FS(10)};font-weight:700;margin-bottom:8px">Heart rate · 7d</div><div class="vg-chart">${bars}</div></div><div class="vg-tiles" style="margin-top:10px">${readings.map(r=>`<div class="tile"><div class="ic">${r[0]}</div><div class="v" style="${FS(13)}">${r[1]}</div><div class="l">${r[2]}</div></div>`).join("")}</div></div>`+tabbar(["Today","Trends","Me"],0);};

// 18. chat-conversation
M["chat-conversation"] = (ctx) => {const msgs=[["Hi! Can you help with the project?",true],["Sure! What do you need?",false],["I need the Q4 report by Friday",true],["On it. I'll have it ready by Thursday.",false],["Perfect, thanks! 🙏",true]];return phoneNav(ctx)+`<div class="vg-scroll" style="flex:1;overflow:auto;padding:10px;display:flex;flex-direction:column;gap:8px">${msgs.map(m=>`<div style="align-self:${m[1]?"flex-end":"flex-start"};max-width:75%;background:${m[1]?"var(--brand-primary)":"var(--brand-surface)"};color:${m[1]?"var(--brand-on-primary)":"var(--brand-text)"};border:1px solid var(--brand-border);border-radius:14px;padding:8px 12px;${FS(10)}">${m[0]}</div>`).join("")}</div><div style="padding:10px;border-top:1px solid var(--brand-border);display:flex;align-items:center;gap:8px"><div style="flex:1;display:flex;align-items:center;gap:6px;padding:8px 12px;border:1px solid var(--brand-border);border-radius:9999px;background:var(--brand-muted)"><span class="vg-muted" style="${FS(10)}">Message…</span></div><div style="width:36px;height:36px;border-radius:9999px;background:var(--brand-primary);display:flex;align-items:center;justify-content:center;color:#fff;${FS(14)}">➤</div></div>`;};

// 19. photo-grid
M["photo-grid"] = (ctx) => phoneNav(ctx)+`<div class="vg-scroll" style="flex:1;overflow:auto"><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:2px">${Array.from({length:18},(_,i)=>`<div style="aspect-ratio:1;background:linear-gradient(${135+i*20}deg,var(--brand-muted),var(--brand-surface));display:flex;align-items:center;justify-content:center"><span class="vg-muted" style="${FS(8)}">${i+1}</span></div>`).join("")}</div></div>`+tabbar(["Photos","Albums","Me"],0);

// 20. profile-tabbed
